#!/usr/bin/env python3
import re
from ta_emss import ta_emss


if __name__ == "__main__":

    ################################################################################
    # Create EMSS instance and setup BTS OAM for 256 X2AP links (default is 64)
    ################################################################################
    emss1 = ta_emss()
    emss1.setup_emss(bts_id=1)
    emss1.configure_bts([{'MOC': 'ANR', 'ID': 0, 'maxNumX2LinksIn': 256}])

    ################################################################################
    # Configure Xterminator with 254 eNBs
    ################################################################################
    print("Setting xterminator up...")
    emss1.xterm_setup(
        # BTS section
        bts_ip_addr="10.0.1.2",
        # ENBsim local IP section
        enbsim_ip_addr_begin="10.0.201.1",
        enbsim_ip_addr_end="10.0.201.254",
        enbsim_ip_addr_mask=24,
        enbsim_eth_if="eth3",
        # ENBsim configuration
        init_enb_pci_max=503,
        init_enb_enb_id=4001,
        init_enb_mcc="440",
        init_enb_mnc="08",
        init_enb_tac=1,
        init_enb_dl_earfcn=4900,
        init_enb_dl_bandwidth=10,
        # X2AP setup configuration
        x2ap_setup_period=15,
        x2ap_setup_retries=3,
        x2ap_reset_period=15,
        x2ap_reset_retries=3,
        # X2AP scenario configuration
        enb_configuration_update_min=60,
        enb_configuration_update_max=300,
        x2_reset_min=300,
        x2_reset_max=360,
        # General params
        verbose=True,
        debug=False,
    )

    ################################################################################
    # Add LNRELs from simulated eNBs to each BTS cell
    ################################################################################

    lncels = emss1.get_existing_objects_of_given_type('LNCEL')
    print("LTE Cells={}".format(lncels))
    moc_tab = []
    for lnrel_id, enb in enumerate(emss1.xterm_get("enbs"), start=1):
        enb_id = enb["ENB_ID"]
        enb_ip = enb["IP_ADDR"]
        mcc = enb["MCC"]
        mnc = enb["MNC"]
        print("ENB={}, mcc={}, mnc={}".format(enb_id, mcc, mnc))
        moc_tab.append({'MOC': 'LNADJ', 'ID': f'{lnrel_id}',
                        'adjEnbId': enb_id,
                        'cPlaneIpAddr': enb_ip,
                        'plmnId': [{'mcc': mcc, 'mnc': mnc, 'mncLength': len(mnc)}]})
        for lncel in lncels:
            lncel_id = re.search(r'(\d+)', lncel).group(1)
            moc_tab.append({'MOC': 'LNREL', 'ID': f'{lncel_id}-{lnrel_id}',
                            'ecgiAdjEnbId': enb_id,
                            'ecgiLcrId': 1,
                            'ecgiPlmnId': [{'mcc': mcc, 'mnc': mnc, 'mncLength': len(mnc)}],
                            'nrControl': 'manual',
                            'removeAllowed': 'false',
            })
    emss1.configure_bts(moc_tab)

    print("Stopping xterm")
    emss1.xterm_teardown()
